"""Resolve PR 319 merge conflicts: keep main's side, then move each
'# owner/action vX' comment onto its 'uses:' line as a trailing '# vTAG'.
The tag comes from the SHA (TAGS map), never from the stale comment."""
import re
import sys

TAGS = {
    "68a389c788b2cd04016ce8c80ee23b80d2ab3d68": "v2.88.1",   # taiki-e/install-action
    "64ab729a6294000f5aa4a4bc0b73d1f32bc45510": "v3.3.0",    # actions/create-github-app-token
    "f67a7e724bdad4a0f6875f186060a0ca2770d76c": "v0.5.147",  # release-plz/action
}
COMMENT = re.compile(r"^\s*# ([\w.-]+/[\w./-]+) v\S+\s*$")
USES = re.compile(r"^(\s*(?:- )?uses: )([\w.-]+/[\w./-]+)@([0-9a-f]{40})\s*$")


def convert(block):
    out, i = [], 0
    while i < len(block):
        c = COMMENT.match(block[i])
        u = USES.match(block[i + 1]) if i + 1 < len(block) else None
        if c and u and c.group(1) == u.group(2):
            sha = u.group(3)
            if sha not in TAGS:
                sys.exit(f"unknown SHA {sha} for {u.group(2)}")
            out.append(f"{u.group(1)}{u.group(2)}@{sha} # {TAGS[sha]}\n")
            i += 2
            continue
        out.append(block[i])
        i += 1
    return out


for path in sys.argv[1:]:
    lines = open(path).readlines()
    res, state, theirs = [], None, []
    for line in lines:
        if line.startswith("<<<<<<< "):
            state, theirs = "ours", []
        elif line.startswith("=======") and state == "ours":
            state = "theirs"
        elif line.startswith(">>>>>>> ") and state == "theirs":
            res.extend(convert(theirs))
            state = None
        elif state == "theirs":
            theirs.append(line)
        elif state is None:
            res.append(line)
    if state is not None:
        sys.exit(f"unterminated conflict in {path}")
    open(path, "w").writelines(res)
    print(f"resolved {path}")

